import { DatabaseSync } from 'node:sqlite';

const db = new DatabaseSync('bookshelf.db');

const insert = db.prepare('INSERT INTO books (title, author, year) VALUES (?, ?, ?)');

const result = insert.run('Dune', 'Frank Herbert', 1965);
console.log('Inserted row', result.lastInsertRowid, 'changes:', result.changes);

insert.run('Neuromancer', 'William Gibson', 1984);
insert.run('Snow Crash', 'Neal Stephenson', 1992);

const { count } = db.prepare('SELECT COUNT(*) AS count FROM books').get();
console.log(`${count} books stored`);

