import { DatabaseSync } from 'node:sqlite';

const db = new DatabaseSync('bookshelf.db');
const insert = db.prepare('INSERT INTO books (title, author, year) VALUES (?, ?, ?)');

const incoming = [
  ['Hyperion', 'Dan Simmons', 1989],
  ['Foundation', 'Isaac Asimov', 1951],
];

db.exec('BEGIN');
try {
  for (const [title, author, year] of incoming) insert.run(title, author, year);
  db.exec('COMMIT');
  console.log(`Imported ${incoming.length} books`);
} catch (error) {
  db.exec('ROLLBACK');
  console.error('Import failed, nothing was saved:', error.message);
}

db.close();

const db = new DatabaseSync('bookshelf.db');

app.get('/api/books', (req, res) => {
  res.json(db.prepare('SELECT * FROM books ORDER BY id').all());
});

app.post('/api/books', (req, res) => {
  const { title, author, year } = req.body ?? {};
  if (typeof title !== 'string' || title.trim() === '') {
    return res.status(400).json({ error: 'title is required' });
  }
  const result = db
    .prepare('INSERT INTO books (title, author, year) VALUES (?, ?, ?)')
    .run(title.trim(), author ?? 'Unknown', year ?? null);
  const book = db.prepare('SELECT * FROM books WHERE id = ?').get(result.lastInsertRowid);
  res.status(201).json(book);
});
